diff --git a/mailnews/base/public/nsICopyMessageStreamListener.idl b/mailnews/base/public/nsICopyMessageStreamListener.idl
index 772a69080b7..c1680dc6384 100644
--- a/mailnews/base/public/nsICopyMessageStreamListener.idl
+++ b/mailnews/base/public/nsICopyMessageStreamListener.idl
@@ -9,12 +9,44 @@
 interface nsICopyMessageListener;
 interface nsIURI;

+/**
+ * A wrapper around `nsICopyMessageListener` to help with reading messages being
+ * copied/moved. Each instance is specific to a single move/copy operation, but
+ * a single operation can span multiple messages.
+ *
+ * @note Implementors should also implement `nsIStreamListener`.
+ */
 [scriptable, uuid(7741DAEC-2125-11d3-8A90-0060B0FC04D2)]
-
 interface nsICopyMessageStreamListener: nsISupports
 {
-  void init(in nsICopyMessageListener destination);
+  /**
+   * Initializes the listener.
+   *
+   * @param destination The listener to forward calls to.
+   * @param isMove      Whether the operation is about moving a message, as
+   *                    opposed to only copying it.
+   */
+  void init(in nsICopyMessageListener destination, in boolean isMove);
+
+  /**
+   * Calls `StartMessage` on the wrapped listener.
+   */
   void startMessage();
+
+  /**
+   * Calls `EndMessage` on the wrapped listener.
+   *
+   * @param key The message's key in the source folder.
+   */
   void endMessage(in nsMsgKey key);
-  void endCopy(in nsIURI uri, in nsresult status);
+
+  /**
+   * Calls `EndCopy` on the wrapped listener, as well as `EndMove` if the
+   * operation is a move.
+   *
+   * Also called through `nsIStreamListener::OnStopRequest`.
+   *
+   * @param status  The end status for the whole operation.
+   */
+  void endCopy(in nsresult status);
 };
diff --git a/mailnews/base/src/nsCopyMessageStreamListener.cpp b/mailnews/base/src/nsCopyMessageStreamListener.cpp
index 343c27ac542..a86d69e5dfe 100644
--- a/mailnews/base/src/nsCopyMessageStreamListener.cpp
+++ b/mailnews/base/src/nsCopyMessageStreamListener.cpp
@@ -19,8 +19,9 @@ nsCopyMessageStreamListener::~nsCopyMessageStreamListener() {
 }

 NS_IMETHODIMP nsCopyMessageStreamListener::Init(
-    nsICopyMessageListener* destination) {
+    nsICopyMessageListener* destination, bool isMove) {
   mDestination = destination;
+  mIsMove = isMove;
   return NS_OK;
 }

@@ -45,38 +46,16 @@ NS_IMETHODIMP nsCopyMessageStreamListener::OnDataAvailable(
 }

 NS_IMETHODIMP nsCopyMessageStreamListener::OnStartRequest(nsIRequest* request) {
-  nsresult rv = NS_OK;
-  nsCOMPtr<nsIURI> uri;
-
-  // We know the request is an nsIChannel we can get a URI from, but this is
-  // probably bad form. See Bug 1528662.
-  nsCOMPtr<nsIChannel> channel = do_QueryInterface(request, &rv);
-  NS_WARNING_ASSERTION(NS_SUCCEEDED(rv),
-                       "error QI nsIRequest to nsIChannel failed");
-  if (NS_SUCCEEDED(rv)) rv = channel->GetURI(getter_AddRefs(uri));
-  if (NS_SUCCEEDED(rv)) rv = mDestination->BeginCopy();
-
-  NS_ENSURE_SUCCESS(rv, rv);
-  return rv;
+  return mDestination->BeginCopy();
 }

-NS_IMETHODIMP nsCopyMessageStreamListener::EndCopy(nsIURI* uri,
-                                                   nsresult status) {
-  nsresult rv;
+NS_IMETHODIMP nsCopyMessageStreamListener::EndCopy(nsresult status) {
   bool copySucceeded = (status == NS_BINDING_SUCCEEDED);
-  rv = mDestination->EndCopy(copySucceeded);
-  // If this is a move and we finished the copy, delete the old message.
-  bool moveMessage = false;
-
-  nsCOMPtr<nsIMsgMailNewsUrl> mailURL(do_QueryInterface(uri));
-  if (mailURL) rv = mailURL->IsUrlType(nsIMsgMailNewsUrl::eMove, &moveMessage);
-
-  if (NS_FAILED(rv)) moveMessage = false;
+  nsresult rv = mDestination->EndCopy(copySucceeded);
+  NS_ENSURE_SUCCESS(rv, rv);

-  // OK, this is wrong if we're moving to an imap folder, for example. This
-  // really says that we were able to pull the message from the source, NOT that
-  // we were able to put it in the destination!
-  if (moveMessage) {
+  // If this is a move and we finished the copy, delete the old message.
+  if (mIsMove) {
     // don't do this if we're moving to an imap folder - that's handled
     // elsewhere.
     nsCOMPtr<nsIMsgImapMailFolder> destImap = do_QueryInterface(mDestination);
@@ -92,15 +71,5 @@ NS_IMETHODIMP nsCopyMessageStreamListener::EndCopy(nsIURI* uri,

 NS_IMETHODIMP nsCopyMessageStreamListener::OnStopRequest(nsIRequest* request,
                                                          nsresult aStatus) {
-  nsresult rv;
-  // We know the request is an nsIChannel we can get a URI from, but this is
-  // probably bad form. See Bug 1528662.
-  nsCOMPtr<nsIChannel> channel = do_QueryInterface(request, &rv);
-  NS_WARNING_ASSERTION(NS_SUCCEEDED(rv),
-                       "error QI nsIRequest to nsIChannel failed");
-  NS_ENSURE_SUCCESS(rv, rv);
-  nsCOMPtr<nsIURI> uri;
-  rv = channel->GetURI(getter_AddRefs(uri));
-  NS_ENSURE_SUCCESS(rv, rv);
-  return EndCopy(uri, aStatus);
+  return EndCopy(aStatus);
 }
